Create backend/src/lib/twilio-send.ts:

```typescript
import twilio from 'twilio';
import { log } from './logger';

interface SendTwilioResult {
  success: boolean;
  sid?: string;
  error?: string;
}

export async function sendTwilioWhatsApp(to: string, body: string): Promise<SendTwilioResult> {
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  const from = process.env.TWILIO_WHATSAPP_NUMBER;

  if (!accountSid || !authToken || !from) {
    log('error', '[Twilio] Missing credentials: TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, or TWILIO_WHATSAPP_NUMBER');
    return { success: false, error: 'Missing Twilio credentials' };
  }

  try {
    const client = twilio(accountSid, authToken);
    const message = await client.messages.create({
      from, // whatsapp:+14155238886
      to: to.startsWith('whatsapp:') ? to : `whatsapp:${to}`,
      body
    });

    log('info', `[Twilio] Message sent to ${to} — SID: ${message.sid}`);
    return { success: true, sid: message.sid };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : String(err);
    log('error', `[Twilio] Error sending message to ${to}:`, errorMsg);
    return { success: false, error: errorMsg };
  }
}
```

No retry logic needed (Twilio has internal retry). Use existing log() function from logger.ts. Handle both whatsapp: prefixed and non-prefixed phone numbers.

Create backend/src/middleware/twilio-webhook.middleware.ts:

```typescript
import { Request, Response, NextFunction } from 'express';
import twilio from 'twilio';
import { log } from '../lib/logger';

export function verifyTwilioSignature(req: Request, res: Response, next: NextFunction) {
  const signature = req.headers['x-twilio-signature'] as string | undefined;

  if (!signature) {
    log('error', '[Twilio] Missing X-Twilio-Signature header');
    res.status(403).json({ error: 'Missing signature' });
    return;
  }

  const authToken = process.env.TWILIO_AUTH_TOKEN;
  if (!authToken) {
    log('error', '[Twilio] TWILIO_AUTH_TOKEN not configured');
    res.status(500).json({ error: 'Server misconfiguration' });
    return;
  }

  // Twilio validates URL + params (form-urlencoded body)
  const url = `https://${req.headers.host}${req.originalUrl}`;
  const params = req.body || {};

  const isValid = twilio.validateRequest(authToken, signature, url, params);

  if (!isValid) {
    log('error', '[Twilio] Invalid webhook signature');
    res.status(403).json({ error: 'Invalid signature' });
    return;
  }

  next();
}
```

Use twilio.validateRequest() from SDK (similar pattern to verifyMetaHmac). Twilio sends form-urlencoded data, not JSON. Signature validates URL + body params.

