import * as fs from 'fs';
import * as path from 'path';

interface FileChunk {
  files: Array<{ name: string; path: string; content: string; size: number; lines: number }>;
  totalSize: number;
}

export async function scanCodebase(): Promise<FileChunk[]> {
  const scanPaths = (process.env.SECURITY_SCAN_PATHS || './src').split(',').map(p => p.trim());
  const MAX_FILE_SIZE = 400 * 1024; // 400KB
  const MAX_CHUNK_SIZE = 80 * 1024; // 80KB
  const INCLUDE_EXTS = ['.ts', '.js', '.json'];
  const EXCLUDE_DIRS = ['node_modules', 'dist', '.git', 'coverage'];
  const EXCLUDE_FILES = ['package-lock.json'];
  const EXCLUDE_PATTERNS = ['.test.ts', '.spec.ts'];

  const allFiles: Array<{name: string; path: string; content: string; size: number; lines: number}> = [];

  function walkDir(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (!EXCLUDE_DIRS.includes(entry.name)) walkDir(fullPath);
      } else {
        const ext = path.extname(entry.name);
        if (INCLUDE_EXTS.includes(ext) && 
            !EXCLUDE_FILES.includes(entry.name) &&
            !EXCLUDE_PATTERNS.some(p => entry.name.includes(p))) {
          const stat = fs.statSync(fullPath);
          if (stat.size > MAX_FILE_SIZE) {
            console.warn(`Skipping large file: ${fullPath} (${stat.size} bytes)`);
            continue;
          }
          const content = fs.readFileSync(fullPath, 'utf8');
          allFiles.push({
            name: entry.name,
            path: fullPath,
            content,
            size: stat.size,
            lines: content.split('\n').length
          });
        }
      }
    }
  }

  for (const scanPath of scanPaths) {
    const resolvedPath = path.resolve(scanPath);
    if (fs.existsSync(resolvedPath)) walkDir(resolvedPath);
  }

  // Chunk files into groups of max 80KB
  const chunks: FileChunk[] = [];
  let currentChunk: FileChunk = { files: [], totalSize: 0 };

  for (const file of allFiles) {
    if (currentChunk.totalSize + file.size > MAX_CHUNK_SIZE && currentChunk.files.length > 0) {
      chunks.push(currentChunk);
      currentChunk = { files: [], totalSize: 0 };
    }
    currentChunk.files.push(file);
    currentChunk.totalSize += file.size;
  }

  if (currentChunk.files.length > 0) chunks.push(currentChunk);
  return chunks;
}

Use path.join(__dirname, ...) for Railway compatibility.

Create analyzer.ts:

import Anthropic from '@anthropic-ai/sdk';
import { Vulnerability } from './types';

const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
const MODEL = 'claude-sonnet-4-6';
const TIMEOUT = 60000;

const SYSTEM_PROMPT = `You are a cybersecurity expert specialized in TypeScript/Node.js/Express code auditing. Analyze the provided source code and return ONLY a valid JSON object, no markdown, no extra text.

JSON schema:
{
  "vulnerabilities": [...],
  "security_score": 75,
  "scan_summary": "Executive summary in 2-3 sentences"
}

Look specifically for: SQL injection in raw Prisma queries, hardcoded secrets, JWT misconfiguration, CORS misconfiguration, missing rate limiting, weak input validation, error handling exposing stack traces, path traversal, prototype pollution, command injection, unvalidated env vars, logging sensitive data, IDOR in Prisma queries.

If no real vulnerabilities found, return empty array with high score. NEVER invent vulnerabilities.`;

interface ChunkAnalysis {
  vulnerabilities: Vulnerability[];
  security_score: number;
  scan_summary: string;
}

export async function analyzeChunk(chunkContent: string, retryCount = 0): Promise<ChunkAnalysis> {
  try {
    const response = await Promise.race([
      client.messages.create({
        model: MODEL,
        max_tokens: 4096,
        system: SYSTEM_PROMPT,
        messages: [{ role: 'user', content: chunkContent }]
      }),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), TIMEOUT))
    ]) as Anthropic.Message;

    const textContent = response.content.find(c => c.type === 'text');
    if (!textContent || textContent.type !== 'text') throw new Error('No text response');

    const jsonMatch = textContent.text.match(/\{[\s\S]*\}/);
    const parsed = JSON.parse(jsonMatch ? jsonMatch[0] : textContent.text);
    return parsed as ChunkAnalysis;
  } catch (err) {
    if (retryCount < 1) {
      console.warn(`Retry analyzing chunk (attempt ${retryCount + 1})`);
      return analyzeChunk(chunkContent, retryCount + 1);
    }
    console.error('Analysis failed:', err);
    return { vulnerabilities: [], security_score: 0, scan_summary: 'Analysis failed' };
  }
}

Use claude-sonnet-4-6 model, 60s timeout, retry once on failure.

