    res.status(400).json({ error: "horaInicio debe tener formato HH:mm (24h)" });
    return;
  }

  const horario = await prisma.horarioClase.create({
    data: { grupoId, diaSemana, horaInicio }
  });

  res.status(201).json(horario);
});
